    "image": [
      {
        "id": "fashion-editorial",
        "label": "Fashion editorial",
        "description": "A clean fashion concept with a full outfit and room for your own campaign copy.",
        "settings": {
          "prompt": "An adult fashion model wearing a tailored cobalt-blue jacket, ivory trousers and simple dark shoes, standing naturally against a warm grey studio wall. Show the complete outfit and both hands. Gentle side light reveals the fabric texture. A restrained editorial composition with clear space beside the model for copy. No lettering, logos or watermarks.",
